head.script:
scwin.ccb_checkcombobox1_oncheckboxclick = function(index, isChecked, value) {
    debugger;
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 필터를 적용하기위해 항목의 header를 클릭하여 필터값을 제외한다
    //2. To apply the filter, click the header of the entry to exclude the filter value.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('ccb_checkcombobox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2table_ccb_col_label')[0].innerText == 'valuetest'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "key": "test",
        "value": "valuetest"
    }, {
        "key": "test1",
        "value": "valuetest1"
    }, {
        "key": "test2",
        "value": "valuetest2"
    }];
    dataList1.setJSON(jsonData);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
